export type ItemCategory =
  | "Weapons"
  | "Chest Armor"
  | "Head Armor"
  | "Foot Armor"
  | "OFF-hands"
  | "Capes"
  | "Bags"
  | "Mount"
  | "Consumable"
  | "Gathering Equipment"
  | "Crafting"
  | "Artifact"
  | "Farming"
  | "Furniture"
  | "Vanity"
  | "Other"
  // Legacy aliases
  | "Melee"
  | "Ranged"
  | "Magic"
  | "Armor"
  | "Refining"
  | "Accessories"
  | "Consumables";

export const ALBION_CATEGORIES = [
  "All",
  "Weapons",
  "Chest Armor",
  "Head Armor",
  "Foot Armor",
  "OFF-hands",
  "Capes",
  "Bags",
  "Mount",
  "Consumable",
  "Gathering Equipment",
  "Crafting",
  "Artifact",
  "Farming",
  "Furniture",
  "Vanity",
  "Other",
] as const;

export type StandardCategory = (typeof ALBION_CATEGORIES)[number];

export function normalizeCategory(cat: ItemCategory | string): StandardCategory {
  if (cat === "Melee" || cat === "Ranged" || cat === "Magic") return "Weapons";
  if (cat === "Refining") return "Crafting";
  if (cat === "Armor") return "Chest Armor";
  if (cat === "Accessories") return "Capes";
  if (cat === "Consumables") return "Consumable";
  return cat as StandardCategory;
}

export type ItemQuality =
  | "Normal"
  | "Good"
  | "Outstanding"
  | "Excellent"
  | "Masterpiece";

export interface CraftingIngredient {
  id: string;
  name: string;
  identifier: string;
  tier: number;
  tierRoman: string;
  enchantment?: number;
  icon: string;
  requiredPerCraft: number;
  baseCost: number;
}

export interface AlbionItem {
  id: string;
  name: string;
  identifier: string;
  tier: number;
  tierRoman: string;
  category: ItemCategory;
  subcategory: string;
  enchantment: number; // 0, 1, 2, 3, 4
  quality: ItemQuality;
  price: number;
  icon: string;
  nutritionPerCraft: number;
  famePerCraft: number;
  subFamePerCraft: number;
  defaultUsageFee: number;
  ingredients: [CraftingIngredient, CraftingIngredient] | CraftingIngredient[];
}

export const getLocalItemIcon = (id: string, enchant = 0) =>
  `/images/items/${id}${enchant > 0 ? `@${enchant}` : ""}.png`;

export const getRemoteItemIcon = (id: string, enchant = 0) =>
  `https://render.albiononline.com/v1/item/${id}${enchant > 0 ? `@${enchant}` : ""}.png`;

export const aoRender = (id: string, enchant = 0) =>
  getLocalItemIcon(id, enchant);

const roman = (t: number) => ["0", "I", "II", "III", "IV", "V", "VI", "VII", "VIII"][t] || "V";

